{"filepath":"scripts/metrics_from_lighthouse.py","content":"#!/usr/bin/env python3
"""
metrics_from_lighthouse.py

Reads one or more Lighthouse JSON output files and computes p50 and p75 for LCP (ms) and CLS.
Dependency-free.
Usage:
  python scripts/metrics_from_lighthouse.py path/to/lh1.json path/to/lh2.json
  python scripts/metrics_from_lighthouse.py --selftest

The script prints a JSON summary to stdout.
"""
import sys
import json
import math
from typing import List, Tuple, Optional


def extract_metrics_from_lh(lh: dict) -> Tuple[Optional[float], Optional[float]]:
    """Try several common Lighthouse JSON shapes to extract LCP (ms) and CLS."""
    # Primary: audits.largest-contentful-paint.numericValue and audits.cumulative-layout-shift.numericValue
    try:
        audits = lh.get('audits', {})
        lcp = audits.get('largest-contentful-paint', {}).get('numericValue')
        cls = audits.get('cumulative-layout-shift', {}).get('numericValue')
        if lcp is not None or cls is not None:
            return (float(lcp) if lcp is not None else None, float(cls) if cls is not None else None)
    except Exception:
        pass

    # Secondary: older/audit metrics might be under audits.metrics.details.items[0]
    try:
        audits = lh.get('audits', {})
        metrics = audits.get('metrics', {})
        details = metrics.get('details', {})
        items = details.get('items', [])
        if items and isinstance(items, list):
            item = items[0]
            # Common keys
            lcp = item.get('largestContentfulPaint') or item.get('LargestContentfulPaint') or item.get('lcp')
            cls = item.get('cumulativeLayoutShift') or item.get('CumulativeLayoutShift') or item.get('cls')
            if lcp is not None or cls is not None:
                return (float(lcp) if lcp is not None else None, float(cls) if cls is not None else None)
    except Exception:
        pass

    # Tertiary: metrics in top-level 'lhr' wrapper
    try:
        lhr = lh.get('lhr', {}) if isinstance(lh, dict) else {}
        audits = lhr.get('audits', {})
        lcp = audits.get('largest-contentful-paint', {}).get('numericValue')
        cls = audits.get('cumulative-layout-shift', {}).get('numericValue')
        if lcp is not None or cls is not None:
            return (float(lcp) if lcp is not None else None, float(cls) if cls is not None else None)
    except Exception:
        pass

    # Not found
    return (None, None)


def nearest_rank(values: List[float], percentile: float) -> Optional[float]:
    if not values:
        return None
    values_sorted = sorted(values)
    n = len(values_sorted)
    # nearest-rank: k = ceil(p/100 * n)
    k = math.ceil(percentile / 100.0 * n)
    idx = max(0, min(n - 1, k - 1))
    return values_sorted[idx]


def summarize(lcp_values: List[float], cls_values: List[float]) -> dict:
    return {
        'lcp_ms': {
            'count': len(lcp_values),
            'p50': nearest_rank(lcp_values, 50),
            'p75': nearest_rank(lcp_values, 75),
        },
        'cls': {
            'count': len(cls_values),
            'p50': nearest_rank(cls_values, 50),
            'p75': nearest_rank(cls_values, 75),
        }
    }


def main(argv):
    if not argv or argv[0] in ('-h', '--help'):
        print(__doc__)
        return 0

    if argv[0] == '--selftest':
        return run_selftest()

    lcp_values = []
    cls_values = []
    for path in argv:
        try:
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            lcp, cls = extract_metrics_from_lh(data)
            if lcp is not None:
                lcp_values.append(float(lcp))
            if cls is not None:
                cls_values.append(float(cls))
        except FileNotFoundError:
            print(f'File not found: {path}', file=sys.stderr)
        except json.JSONDecodeError:
            print(f'Invalid JSON: {path}', file=sys.stderr)
        except Exception as e:
            print(f'Error reading {path}: {e}', file=sys.stderr)

    if not lcp_values and not cls_values:
        print('No LCP or CLS metrics found in inputs', file=sys.stderr)
        return 2

    summary = summarize(lcp_values, cls_values)
    print(json.dumps(summary, indent=2))
    return 0


def run_selftest() -> int:
    import os
    thisdir = os.path.dirname(__file__)
    sample1 = os.path.join(thisdir, '..', 'sample_data', 'lh_sample_1.json')
    sample2 = os.path.join(thisdir, '..', 'sample_data', 'lh_sample_2.json')
    # Basic sanity run
    try:
        rc = main([sample1, sample2])
        # Expect rc == 0 (found metrics)
        if rc != 0:
            print('Selftest failed: non-zero exit', file=sys.stderr)
            return 3
    except Exception as e:
        print('Selftest exception: ' + str(e), file=sys.stderr)
        return 4
    # Additionally test the parser directly
    with open(sample1, 'r', encoding='utf-8') as f:
        d1 = json.load(f)
    with open(sample2, 'r', encoding='utf-8') as f:
        d2 = json.load(f)
    l1, c1 = extract_metrics_from_lh(d1)
    l2, c2 = extract_metrics_from_lh(d2)
    # sample values are known
    assert l1 == 1600.0, 'unexpected lcp in sample1'
    assert c1 == 0.12, 'unexpected cls in sample1'
    assert l2 == 2200.0, 'unexpected lcp in sample2'
    assert c2 == 0.25, 'unexpected cls in sample2'
    # Test summary calculations
    summary = summarize([l1, l2], [c1, c2])
    assert summary['lcp_ms']['p50'] in (1600.0, 2200.0), 'p50 unexpected'
    assert summary['lcp_ms']['p75'] in (1600.0, 2200.0), 'p75 unexpected'
    print('Selftest passed')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
"}
